CREATE TABLE IF NOT EXISTS `lead_follow_ups` (`id` int NOT NULL AUTO_INCREMENT, `lead_id` int NOT NULL, `attempt` int NOT NULL, `sub_attempt` int NOT NULL, `scheduled_at` timestamp NOT NULL, `executed_at` timestamp NULL, `status` enum('pending','sent','responded','failed','cancelled') NOT NULL DEFAULT 'pending', `message` text NULL, `response` text NULL, `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
